-- =============================================================================
-- COMPLETE DATABASE SETUP SCRIPT FOR INVENTORY MANAGEMENT SYSTEM (SQL SERVER)
-- Includes:
-- 1. Auto-Drop Foreign Keys & Existing Tables/Views
-- 2. Create Schema (Categories, Products, Stock Movements, BOM, Inventory View)
-- 3. Insert Master & Transaction Data (Categories, 1,215 Products, 8,339 Movements)
-- =============================================================================

SET NOCOUNT ON;
GO

-- =============================================================================
-- SECTION 1: DROP FOREIGN KEYS & EXISTING TABLES/VIEWS
-- =============================================================================
DECLARE @sql NVARCHAR(MAX) = N'';

SELECT @sql += N'ALTER TABLE ' + QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id))
    + '.' + QUOTENAME(OBJECT_NAME(parent_object_id)) 
    + ' DROP CONSTRAINT ' + QUOTENAME(name) + ';' + CHAR(13)
FROM sys.foreign_keys
WHERE referenced_object_id IN (
    OBJECT_ID('categories'),
    OBJECT_ID('products'),
    OBJECT_ID('bom_recipes'),
    OBJECT_ID('bom_items'),
    OBJECT_ID('stock_movements')
)
OR parent_object_id IN (
    OBJECT_ID('categories'),
    OBJECT_ID('products'),
    OBJECT_ID('bom_recipes'),
    OBJECT_ID('bom_items'),
    OBJECT_ID('stock_movements')
);

IF @sql <> N''
    EXEC sp_executesql @sql;
GO

DROP VIEW IF EXISTS v_current_inventory;
GO

DROP TABLE IF EXISTS bom_items;
DROP TABLE IF EXISTS bom_recipes;
DROP TABLE IF EXISTS stock_movements;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
GO

-- =============================================================================
-- SECTION 2: CREATE TABLES & VIEW
-- =============================================================================

-- 2.1 ตารางหมวดหมู่สินค้าหลัก (RM, PK, FG)
CREATE TABLE categories (
    category_id VARCHAR(10) PRIMARY KEY,
    category_name NVARCHAR(100) NOT NULL,
    description NVARCHAR(MAX)
);
GO

-- 2.2 ตารางทะเบียนสินค้า / วัตถุดิบ / บรรจุภัณฑ์
CREATE TABLE products (
    item_code VARCHAR(50) PRIMARY KEY,
    thai_code VARCHAR(50),
    product_name NVARCHAR(255) NOT NULL,
    category_id VARCHAR(10) NOT NULL,
    product_type NVARCHAR(50),
    unit NVARCHAR(20) NOT NULL,
    cost_price DECIMAL(15, 4) DEFAULT 0.0000,
    min_stock DECIMAL(15, 4) DEFAULT 0.0000,
    safe_stock DECIMAL(15, 4) DEFAULT 0.0000,
    units_per_box DECIMAL(10, 2),
    units_per_pallet DECIMAL(10, 2),
    buyer_customer NVARCHAR(100),
    created_at DATETIME2 DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_products_category 
        FOREIGN KEY (category_id) REFERENCES categories(category_id)
        ON UPDATE CASCADE ON DELETE NO ACTION
);
GO

-- 2.3 ตารางบันทึกการเคลื่อนไหวคลังสินค้า (Stock Movement Log)
CREATE TABLE stock_movements (
    movement_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    movement_date DATE NOT NULL,
    document_no NVARCHAR(100),
    item_code VARCHAR(50) NOT NULL,
    movement_type VARCHAR(20) NOT NULL, -- 'IN', 'OUT', 'ADJUST'
    quantity DECIMAL(15, 4) NOT NULL,
    unit_price DECIMAL(15, 4) NULL,
    lot_no NVARCHAR(100),
    ana_no NVARCHAR(100),
    remark NVARCHAR(MAX),
    created_at DATETIME2 DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_movements_product 
        FOREIGN KEY (item_code) REFERENCES products(item_code)
        ON UPDATE CASCADE ON DELETE NO ACTION
);
GO

-- 2.4 ตารางสูตรการผลิต (BOM Master)
CREATE TABLE bom_recipes (
    bom_id INT IDENTITY(1,1) PRIMARY KEY,
    fg_item_code VARCHAR(50) NOT NULL,
    recipe_name NVARCHAR(255) NOT NULL,
    standard_batch_size DECIMAL(15, 4),
    yield_unit NVARCHAR(20),
    is_active BIT DEFAULT 1,
    CONSTRAINT fk_bom_fg 
        FOREIGN KEY (fg_item_code) REFERENCES products(item_code)
        ON UPDATE CASCADE ON DELETE NO ACTION
);
GO

-- 2.5 ตารางรายการส่วนผสมและบรรจุภัณฑ์ในสูตร BOM
CREATE TABLE bom_items (
    bom_item_id BIGINT IDENTITY(1,1) PRIMARY KEY,
    bom_id INT NOT NULL,
    ingredient_code VARCHAR(50) NOT NULL,
    quantity_required DECIMAL(15, 4) NOT NULL,
    unit NVARCHAR(20) NOT NULL,
    percentage DECIMAL(8, 4),
    CONSTRAINT fk_bom_recipe 
        FOREIGN KEY (bom_id) REFERENCES bom_recipes(bom_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_bom_ingredient 
        FOREIGN KEY (ingredient_code) REFERENCES products(item_code)
        ON UPDATE CASCADE ON DELETE NO ACTION
);
GO

-- 2.6 View สรุปยอดคงเหลือ (On-Hand) ปัจจุบัน
CREATE VIEW v_current_inventory AS
SELECT 
    p.item_code,
    p.thai_code,
    p.product_name,
    p.category_id,
    p.unit,
    p.min_stock,
    p.safe_stock,
    COALESCE(SUM(CASE WHEN sm.movement_type = 'IN' THEN sm.quantity ELSE 0 END), 0) AS total_inbound,
    COALESCE(SUM(CASE WHEN sm.movement_type = 'OUT' THEN sm.quantity ELSE 0 END), 0) AS total_outbound,
    COALESCE(SUM(CASE 
        WHEN sm.movement_type = 'IN' THEN sm.quantity 
        WHEN sm.movement_type = 'OUT' THEN -sm.quantity 
        ELSE 0 
    END), 0) AS on_hand_qty
FROM products p
LEFT JOIN stock_movements sm ON p.item_code = sm.item_code
GROUP BY p.item_code, p.thai_code, p.product_name, p.category_id, p.unit, p.min_stock, p.safe_stock;
GO

